),
gkg_raw AS (
  SELECT
    PARSE_TIMESTAMP('%Y%m%d%H%M%S', CAST(`DATE` AS STRING), 'UTC') AS published_at,
    DocumentIdentifier AS url,
    TRIM(DocumentIdentifier) AS normalized_url,
    LOWER(COALESCE(V2Locations, '')) AS locations_lower,
    LOWER(COALESCE(REGEXP_EXTRACT(Extras, r'<PAGE_TITLE>([^<]*)</PAGE_TITLE>'), '')) AS title_lower,
    CASE
      WHEN REGEXP_EXTRACT(COALESCE(TranslationInfo, ''), r'srclc:([a-z]{3})') = 'eng' THEN 'en'
      ELSE COALESCE(REGEXP_EXTRACT(COALESCE(TranslationInfo, ''), r'srclc:([a-z]{3})'), 'en')
    END AS source_lang,
    GKGRECORDID AS gkg_record_id,
    LOWER(COALESCE(SourceCommonName, '')) AS source_domain,
    REGEXP_EXTRACT(Extras, r'<PAGE_TITLE>([^<]*)</PAGE_TITLE>') AS title,
    REGEXP_EXTRACT(Extras, r'<PAGE_AUTHORS>([^<]*)</PAGE_AUTHORS>') AS authors,
    SAFE_CAST(SPLIT(COALESCE(V2Tone, ''), ',')[SAFE_OFFSET(0)] AS FLOAT64) AS tone,
    NULLIF(SharingImage, '') AS sharing_image
  FROM `gdelt-bq.gdeltv2.gkg_partitioned`
  WHERE (
        (_PARTITIONTIME >= TIMESTAMP('2015-05-17') AND _PARTITIONTIME < TIMESTAMP('2015-05-31'))
        OR (_PARTITIONTIME >= TIMESTAMP('2015-06-19') AND _PARTITIONTIME < TIMESTAMP('2015-07-07'))
        OR (_PARTITIONTIME >= TIMESTAMP('2015-07-14') AND _PARTITIONTIME < TIMESTAMP('2015-07-29'))
        OR (_PARTITIONTIME >= TIMESTAMP('2015-08-28') AND _PARTITIONTIME < TIMESTAMP('2015-09-11'))
        OR (_PARTITIONTIME >= TIMESTAMP('2015-11-08') AND _PARTITIONTIME < TIMESTAMP('2015-11-22'))
        OR (_PARTITIONTIME >= TIMESTAMP('2016-06-25') AND _PARTITIONTIME < TIMESTAMP('2016-08-15'))
        OR (_PARTITIONTIME >= TIMESTAMP('2017-06-25') AND _PARTITIONTIME < TIMESTAMP('2017-07-15'))
        OR (_PARTITIONTIME >= TIMESTAMP('2017-08-11') AND _PARTITIONTIME < TIMESTAMP('2017-09-12'))
        OR (_PARTITIONTIME >= TIMESTAMP('2017-10-30') AND _PARTITIONTIME < TIMESTAMP('2017-11-13'))
        OR (_PARTITIONTIME >= TIMESTAMP('2018-05-29') AND _PARTITIONTIME < TIMESTAMP('2018-06-12'))
        OR (_PARTITIONTIME >= TIMESTAMP('2018-08-02') AND _PARTITIONTIME < TIMESTAMP('2018-08-21'))
        OR (_PARTITIONTIME >= TIMESTAMP('2019-06-28') AND _PARTITIONTIME < TIMESTAMP('2019-07-12'))
        OR (_PARTITIONTIME >= TIMESTAMP('2019-07-14') AND _PARTITIONTIME < TIMESTAMP('2019-07-28'))
        OR (_PARTITIONTIME >= TIMESTAMP('2019-10-19') AND _PARTITIONTIME < TIMESTAMP('2019-11-02'))
        OR (_PARTITIONTIME >= TIMESTAMP('2019-11-29') AND _PARTITIONTIME < TIMESTAMP('2019-12-13'))
        OR (_PARTITIONTIME >= TIMESTAMP('2020-05-24') AND _PARTITIONTIME < TIMESTAMP('2020-06-07'))
        OR (_PARTITIONTIME >= TIMESTAMP('2020-10-01') AND _PARTITIONTIME < TIMESTAMP('2020-10-15'))
        OR (_PARTITIONTIME >= TIMESTAMP('2021-06-01') AND _PARTITIONTIME < TIMESTAMP('2021-06-15'))
        OR (_PARTITIONTIME >= TIMESTAMP('2021-07-01') AND _PARTITIONTIME < TIMESTAMP('2021-07-15'))
        OR (_PARTITIONTIME >= TIMESTAMP('2021-09-13') AND _PARTITIONTIME < TIMESTAMP('2021-09-27'))
        OR (_PARTITIONTIME >= TIMESTAMP('2021-10-11') AND _PARTITIONTIME < TIMESTAMP('2021-11-01'))
        OR (_PARTITIONTIME >= TIMESTAMP('2021-11-18') AND _PARTITIONTIME < TIMESTAMP('2021-12-02'))
        OR (_PARTITIONTIME >= TIMESTAMP('2022-05-17') AND _PARTITIONTIME < TIMESTAMP('2022-05-31'))
        OR (_PARTITIONTIME >= TIMESTAMP('2023-06-26') AND _PARTITIONTIME < TIMESTAMP('2023-07-10'))
        OR (_PARTITIONTIME >= TIMESTAMP('2023-12-18') AND _PARTITIONTIME < TIMESTAMP('2024-01-01'))
      )
      AND `DATE` >= 20150517000000
      AND `DATE` < 20240101000000
      AND DocumentIdentifier IS NOT NULL
      AND EXISTS (SELECT 1 FROM UNNEST(SPLIT(COALESCE(V2Locations, ''), ';')) AS location_ref WHERE UPPER(SPLIT(location_ref, '#')[SAFE_OFFSET(2)]) = 'IN')
      AND EXISTS (SELECT 1 FROM UNNEST(SPLIT(COALESCE(V2Themes, ''), ';')) AS theme_ref WHERE SPLIT(theme_ref, ',')[SAFE_OFFSET(0)] IN UNNEST(['NATURAL_DISASTER_FLOOD', 'NATURAL_DISASTER_FLOODING', 'NATURAL_DISASTER_FLOODS', 'NATURAL_DISASTER_FLOODED', 'NATURAL_DISASTER_FLOODED_AREAS', 'NATURAL_DISASTER_FLOODED_ROAD', 'NATURAL_DISASTER_FLOODED_ROADS', 'NATURAL_DISASTER_FLOODWATER', 'NATURAL_DISASTER_FLOODWATERS', 'NATURAL_DISASTER_FLOOD_WARNING', 'NATURAL_DISASTER_FLOOD_WATER', 'NATURAL_DISASTER_FLOOD_WATERS', 'NATURAL_DISASTER_FLASH_FLOOD', 'NATURAL_DISASTER_FLASH_FLOODS']))
),
gkg AS (
  SELECT * FROM gkg_raw
  WHERE source_lang IN UNNEST(['en', 'ara', 'ben', 'guj', 'hin', 'kan', 'mal', 'mar', 'nep', 'ori', 'pan', 'pus', 'snd', 'tam', 'tel', 'urd'])
),
candidate_matches AS (
  SELECT e.event_district_id, e.event_id, e.source_record_id, e.state, e.district,
         e.onset_date, g.*,
         CASE WHEN EXISTS (
    SELECT 1
    FROM UNNEST(SPLIT(g.locations_lower, ';')) AS location_ref
    CROSS JOIN UNNEST(e.district_terms) AS district_term
    WHERE SPLIT(location_ref, '#')[SAFE_OFFSET(2)] = 'in'
      AND EXISTS (
        SELECT 1 FROM UNNEST(SPLIT(COALESCE(SPLIT(location_ref, '#')[SAFE_OFFSET(1]), ''), ',')) AS location_part
        WHERE TRIM(location_part) = district_term
      )
      AND EXISTS (
        SELECT 1
        FROM UNNEST(SPLIT(COALESCE(SPLIT(location_ref, '#')[SAFE_OFFSET(1]), ''), ',')) AS state_location_part
        CROSS JOIN UNNEST(e.state_terms) AS state_term
        WHERE TRIM(state_location_part) = state_term
      )
  ) THEN 'gkg_location' ELSE 'title' END AS district_evidence,
         ABS(DATE_DIFF(DATE(g.published_at), e.onset_date, DAY)) AS onset_distance
  FROM event_windows e
  JOIN gkg AS g
    ON DATE(g.published_at) >= e.query_start
   AND DATE(g.published_at) < e.query_end_exclusive
  WHERE EXISTS (
    SELECT 1
    FROM UNNEST(SPLIT(g.locations_lower, ';')) AS location_ref
    CROSS JOIN UNNEST(e.district_terms) AS district_term
    WHERE SPLIT(location_ref, '#')[SAFE_OFFSET(2)] = 'in'
      AND EXISTS (
        SELECT 1 FROM UNNEST(SPLIT(COALESCE(SPLIT(location_ref, '#')[SAFE_OFFSET(1]), ''), ',')) AS location_part
        WHERE TRIM(location_part) = district_term
      )
      AND EXISTS (
        SELECT 1
        FROM UNNEST(SPLIT(COALESCE(SPLIT(location_ref, '#')[SAFE_OFFSET(1]), ''), ',')) AS state_location_part
        CROSS JOIN UNNEST(e.state_terms) AS state_term
        WHERE TRIM(state_location_part) = state_term
      )
  )
),
deduplicated AS (
  SELECT * EXCEPT(assignment_rank, onset_distance)
  FROM (
    SELECT *, ROW_NUMBER() OVER (
      PARTITION BY normalized_url, state, district
      ORDER BY onset_distance, onset_date, event_district_id, published_at, url
    ) AS assignment_rank
    FROM candidate_matches
  )
  WHERE assignment_rank = 1
)
SELECT event_district_id, event_id, source_record_id, state, district,
       onset_date, published_at, url, normalized_url, source_domain, source_lang,
       gkg_record_id, title, authors, tone, sharing_image, district_evidence, locations_lower
FROM deduplicated
ORDER BY event_district_id, published_at, normalized_url
